def can_make_abc(cards):
    # Check if the cards can be rearranged to form 'abc'
    if 'abc' in cards:
        return "YES"

    # Check if we can make the cards 'abc' by swapping
    for i in range(len(cards)):
        for j in range(i+1, len(cards)):
            if cards[i] == cards[j] and cards[i] != 'a':
                return "NO"

    return "YES"

