def min_operations_to_remove_black_cells(n, k, s):
    black_cells = [i for i in range(n) if s[i] == 'B']
    operations = 0

    for i in range(len(black_cells) - k + 1):
        operations += black_cells[i + k - 1] - black_cells[i]

    return operations

