    for i in range(len(nums)):
        for j in range(i, len(nums)):
            if nums[i] == nums[j] and j - i + 1 <= k:
                max_len = max(max_len, j - i + 1)
    return max_len

def serversNotRequested(n, logs, x, queries):
    result = []
    for query in queries:
        start = query - x
        end = query
        count = 0
        for log in logs:
            if log[0] >= start and log[0] <= end:
                count += 1
        result.append(n - count)
    return result

