def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)
    if n == 1:
        return 1

    dp = [[0]*n for _ in range(n)]
    dp[0][0] = 1

    for i in range(1, n):
        for j in range(i):
            if nums[j] % nums[i] == 0 or nums[i] % nums[j] == 0:
