def canMakeAllZero(nums, k):
    if k == 0:
        return False

    # Create a new array with the same length as nums
    new_nums = nums.copy()

    # Iterate over the new array
    for i in range(len(new_nums)):
        # Check if the current element is 0
        if new_nums[i] == 0:
            return True

        # If the current element is not 0, we need to decrease it
        if new_nums[i] != 0:
            # Decrease the current element by 1
            new_nums[i] -= 1

            # Check if the new element is 0
            if new_nums[i] == 0:
                return True

    # If we have iterated over the entire array and still haven't made all elements 0
    return False

