import math

def maxElementSum(nums):
    n = len(nums)
    max_sum = 0
    for i in range(1, n+1):
        for j in range(i+1, n+1):
            if all(i*j*i*j % k == 0 for k in range(1, int(math.sqrt(i*j)) + 1)):
                max_sum = max(max_sum, i + j)
    return max_sum

def maxSubarrays(nums):
    n = len(nums)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + nums[i - 1]
    for i in range(n - 1, -1, -1):
        dp[i] = min(dp[i], dp[i + 1] + nums[i])
    return dp[0]

def countSubMultisets(nums, l, r):
    MOD = 10**9 + 7
    count = [0] * (r + 1)
    count[0] = 1

    for num in nums:
        for i in range(l, r + 1):
            count[i] = (count[i] + count[i - num]) % MOD

    return count[r] - count[l - 1]

