def minOperations(nums):
    count = Counter(nums)
    if not count:
        return -1

    operations = 0
    for num in count:
        if count[num] == 1:
            operations += 1
            count[num] -= 1
        elif count[num] == 2:
            count[num] -= 2
            count[num] -= 1
        elif count[num] == 3:
            count[num] -= 3
            count[num] -= 1

    return operations

