def shortestSubarray(nums, target):
    nums.append(0)
    nums.sort()
    left = 0
    min_length = float('inf')

    for right in range(len(nums)):
        while nums[right] - nums[left] > target:
            left += 1
        min_length = min(min_length, right - left + 1)

    return min_length if min_length != float('inf') else -1

def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    nums.sort()

    def get_max_and_min(nums):
        max_and = nums[0]
        min_and = nums[0]
        for num in nums[1:]:
            max_and = max(max_and, num)
            min_and = min(min_and, num)
        return max_and, min_and

    def get_sum_of_squares(max_and, min_and):
        return (max_and * max_and + min_and * min_and) % MOD

    max_and, min_and = get_max_and_min(nums)
    return get_sum_of_squares(max_and, min_and)

