    health = H

    # Iterate over each move
    for i in range(N):
        # Determine the new position based on the move
        if S[i] == 'R':
            new_x, new_y = x_list[i] + 1, y_list[i]
        elif S[i] == 'L':
            new_x, new_y = x_list[i] - 1, y_list[i]
        elif S[i] == 'U':
            new_x, new_y = x_list[i], y_list[i] + 1
        elif S[i] == 'D':
            new_x, new_y = x_list[i], y_list[i] - 1

        # Check if the new position is within the bounds and not an item
        if 0 <= new_x < 2 * 10**5 and 0 <= new_y < 2 * 10**5 and (new_x, new_y) not in x_list and (new_x, new_y) not in y_list:
            # Check if the new health is less than K
            if health < K:
                # If the new health is less than K, consume the item
                health = K
            else:
                # If the new health is not less than K, move to the new position
                health = 0

        # Check if the new health is zero
        if health == 0:
            # If the new health is zero, Takahashi collapses
            return "No"

    # If all moves are completed without collapsing
    return "Yes"

