MOD = 998244353

def count_ways(N, M):
    if N == 1:
        return M % MOD
    if N == 2:
        return (M * (M - 1)) % MOD
    if N == 3:
        return (M * (M - 1) * (M - 2)) % MOD
    if N == 4:
        return (M * (M - 1) * (M - 2) * (M - 3)) % MOD

    # For N > 3, we need to consider the circular arrangement
    # We can use dynamic programming to solve this problem

    # Initialize dp[i][j] as the number of ways to distribute integers to persons 1 to i
    # such that persons 1 to i have integers from 0 to j
    dp = [[0] * (M + 1) for _ in range(N + 1)]

    # Base case: for N = 1, there are M ways
    for j in range(M + 1):
        dp[1][j] = j

    # Fill the dp table
    for i in range(2, N + 1):
        for j in range(M + 1):
            dp[i][j] = sum(dp[i - 1][k] for k in range(j + 1)) % MOD

    # The answer is the number of ways to distribute integers to persons 1 to N such that persons 1 to N have integers from 0 to M-1
    return dp[N][M]

