def find_middle_day(M, D):
    total_days = sum(D)
    middle_day = (total_days + 1) // 2

    for a in range(1, M + 1):
        for b in range(1, M + 1):
            if (a * M + b) % total_days == middle_day:
                return f"{a} {b}"

    return "No solution found"

