def max_weight_edges(N, D):
    # Initialize the dp array with -1
    dp = [[-1 for _ in range(N+1)] for _ in range(N+1)]

    # Base case: if we have chosen 0 edges, the weight is 0
    for i in range(N+1):
        dp[i][0] = 0

    # Fill the dp array
    for i in range(1, N+1):
        for j in range(1, N+1):
            for k in range(1, i):
                if dp[k][j-1] != -1:
                    dp[i][j] = max(dp[i][j], dp[k][j-1] + D[k-1][j-1])

    # The answer is the maximum weight of the edges chosen so far
    return dp[N][N]

