def find_rank(N, S):
    wins = [0] * N
    for i in range(N):
        for j in range(N):
            if S[i] == '-' and S[j] == '-':
                wins[i] += 1
            elif S[i] == '-' and S[j] == 'o':
                wins[j] += 1
            elif S[i] == 'o' and S[j] == '-':
                wins[j] += 1

    rank = [i for i, w in enumerate(wins) if w > 0]
    rank.sort(reverse=True)

    return rank

