def solve_grid(N, R, C):
    # Initialize the grid with empty cells
    grid = [['.' for _ in range(N)] for _ in range(N)]

    # Check if the first row and first column match the given strings R and C
    for i in range(N):
        if grid[i][0] != R[i]:
            return "No"
        if grid[0][i] != C[i]:
            return "No"

    # Fill the rest of the grid
    for i in range(N):
        for j in range(N):
            if grid[i][j] == '.':
                if R[i] != grid[i][j]:
                    return "No"
                if C[j] != grid[i][j]:
                    return "No"
                grid[i][j] = 'A' if R[i] == 'A' else 'B' if R[i] == 'B' else 'C'

