def takahashi_adventure(N, events):
    potions = {}
    monsters = {}
    actions = []

    for t, x in events:
        if t == 1:
            if x in potions:
                actions.append(1)
                potions[x] -= 1
            else:
                actions.append(0)
        else:
            if x in monsters:
                if x in potions:
                    actions.append(1)
                    potions[x] -= 1
                else:
                    actions.append(0)
            else:
                actions.append(0)

    K_min = max(potions.values())
    actions_K_min = [0] * N

    for i in range(N):
        if actions[i] == 1:
            actions_K_min[i] = 1
        else:
            actions_K_min[i] = 0

    for i in range(N):
        if actions_K_min[i] == 1:
            actions[i] = 1

    if K_min == 0:
        return -1

    return K_min, actions_K_min

