def min_tour_length(N, M, X):
    # Initialize the distance matrix with infinity
    dist = [[float('inf')] * (N + 1) for _ in range(N + 1)]

    # Set the distance between the first two islands to 0
    for i in range(1, N + 1):
        dist[1][i] = 0

    # Set the distance between the first two islands to 1
    for i in range(2, N + 1):
        dist[1][i] = 1

    # Floyd-Warshall algorithm
    for k in range(1, N + 1):
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Find the minimum tour length
    min_tour_length = float('inf')
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if dist[i][j] < min_tour_length:
                min_tour_length = dist[i][j]

    return min_tour_length

