import sys
from collections import defaultdict

def find_min_weight_walk(N, M, edges):
    # Create adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Initialize visited array
    visited = [False] * (N + 1)

    # Initialize min_weight variable
    min_weight = float('inf')

    # Function to check if a walk exists
    def is_walkable(start, end):
        if start == end:
            return True
        for u, v, w in graph[start]:
            if visited[u] and visited[v]:
                return True
        return False

    # Function to find the minimum weight walk
    def find_min_weight_walk():
        for start in range(1, N + 1):
            if not visited[start]:
                if is_walkable(start, start):
                    min_weight = min(min_weight, sum(w for _, w in graph[start]))
        return min_weight

    # Find the minimum weight walk
    min_weight_walk = find_min_weight_walk()

    # Print the result
    if min_weight_walk != float('inf'):
        print(min_weight_walk)
    else:
        print("No")

