def count_cells(H, W, N, T, S):
    # Initialize dp array
    dp = [[0] * W for _ in range(H)]

    # Base case: starting point
    dp[0][0] = 1

    # Fill dp array
    for i in range(H):
        for j in range(W):
            if i == 0 and j == 0:
                continue
            if T[i-1] == 'L':
                dp[i][j] += dp[i-1][j]
            elif T[i-1] == 'R':
                dp[i][j] += dp[i][j+1]
            elif T[i-1] == 'U':
                dp[i][j] += dp[i-1][j-1]
            elif T[i-1] == 'D':
                dp[i][j] += dp[i+1][j]

    return dp[H-1][W-1]

