def solve_problem(N, A, M, B, L, C, X):
    # Create a dictionary to store the sum of each combination of A, B, and C
    sum_dict = {}
    for i in range(N):
        for j in range(M):
            for k in range(L):
                sum_dict[(A[i], B[j], C[k])] = sum_dict.get((A[i], B[j], C[k]), 0) + A[i] + B[j] + C[k]

    # Check if the sum of X_i for each i is possible
    for i in range(Q):
        if sum_dict.get((X[i], *B), 0) not in sum_dict:
            return "No"
        if sum_dict.get((X[i], *C), 0) not in sum_dict:
            return "No"
        if sum_dict.get((X[i], *A), 0) not in sum_dict:
            return "No"

    return "Yes"

