def min_cost_to_make_good_string(N, S, C):
    # Initialize the cost array
    cost = [0] * (N + 1)

    # Iterate over each character in the string
    for i in range(N):
        if S[i] == '0':
            # If the character is 0, we can replace it with 1
            cost[i + 1] = C[i]
        else:
            # If the character is 1, we can replace it with 0
            cost[i + 1] = C[i]

    # Calculate the minimum cost to make the string good
    min_cost = cost[0]
    for i in range(1, N):
        if S[i] == S[i - 1]:
            # If the i-th character is the same as the previous one, we need to replace it
            min_cost += cost[i - 1]

    return min_cost

def process_queries(N, Q, queries):
    A = [0] * N
    S = set()

    for x in queries:
        if x in S:
            S.remove(x)
        else:
            S.add(x)

        for j in S:
            A[j] += len(S)

    return A

def can_reach_goal(H, W, grid, medicines):
    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

