def minMoves(nums, k, maxChanges):
    n = len(nums)
    if k == 0:
        return 0
    if k == n:
        return 0
    if k > n:
        return -1

    # Initialize the array to store the number of ones picked up
    ones_picked = [0] * n

    # Initialize the number of ones picked up
    ones_picked[0] = nums[0]

    # Initialize the number of changes made
    changes = 0

    # Iterate over the array
    for i in range(1, n):
        if nums[i] == 1:
            ones_picked[i] = ones_picked[i-1] + 1
        else:
            ones_picked[i] = ones_picked[i-1]

        # Update the number of changes made
        if i > 0 and nums[i] == 0:
            changes += 1

        # If the number of ones picked up is greater than k, return -1
        if ones_picked[i] > k:
            return -1

    # If the number of ones picked up is less than k, return -1
    if ones_picked[n-1] < k:
        return -1

    # If the number of ones picked up is equal to k, return the number of moves
    return n - ones_picked[n-1]

