def min_max_distance(points):
    n = len(points)
    if n < 2:
        return 0

    # Create a dictionary to store the minimum distance between each pair of points
    distances = {}
    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = points[i]
            x2, y2 = points[j]
            distance = abs(x1 - x2) + abs(y1 - y2)
            if (x1, y1) not in distances or distance < distances[(x1, y1)]:
                distances[(x1, y1)] = distance

    # Find the minimum possible value for maximum distance after removing exactly one point
    min_max_distance = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) not in distances:
                distance = distances[(i, j)]
                min_max_distance = min(min_max_distance, distance)

    return min_max_distance

def min_operations(nums, k):
    nums.sort()
    median = nums[len(nums) // 2]
    operations = 0
    for num in nums:
        if num == median:
            continue
        if num < median:
            operations += 1
        else:
            operations += abs(num - median)
    return operations

