def minimumSum(nums, andValues):
    n = len(nums)
    m = len(andValues)
    dp = [[float('inf')] * (1 << m) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1 << m):
            for k in range(1, m):
                if (j & (1 << k)) == 0:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + nums[i - 1])
                else:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + nums[i - 1])

    if dp[n][1 << m] == float('inf'):
        return -1
    else:
        return dp[n][1 << m]

