def minLevelsToWin(possible):
    n = len(possible)
    dp = [[-1 for _ in range(n+1)] for _ in range(n+1)]

    def dfs(i, j):
        if dp[i][j] != -1:
            return dp[i][j]

        if i == n:
            return 0

        if j == n:
            return 1

        if possible[i] == 0:
            dp[i][j] = dfs(i+1, j) + dfs(i+1, j-1)
        else:
            dp[i][j] = dfs(i+1, j) + dfs(i+1, j-1)

        return dp[i][j]

    return dfs(0, 0)

